/* eslint-disable solid/no-innerhtml */

import { createEffect, createMemo, For, Show, type Component } from "solid-js";

import type { ActivatableAudio } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { ChooserItem } from "#core/ui-next/components/chooser-item.jsx";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { TooltipHorizontalPosition, TooltipVerticalPosition } from "#core/ui-next/components/tooltip.jsx";

import { ProductionPanelCategory, type YieldValue } from "#base/ui/production-chooser/production-chooser-helpers.js";
import { AdvisorRecommendations, AdvisorUtilities } from "#base/ui/tutorial/advisor-utilities.js";
import { AdvisorRecommendationsList } from "#base/ui-next/components/advisor-recommendation.jsx";
import { PillText } from "#base/ui-next/components/pills.jsx";
import { ProductionTooltip } from "#base/ui-next/tooltips/production-tooltip.jsx";

type AttrMap = Readonly<Record<string, string | null>>;

const parseJSON = <T,>(value: string | null | undefined, fallback: T): T => {
	if (!value) {
		return fallback;
	}
	try {
		return JSON.parse(value) as T;
	} catch (error) {
		console.error("production-chooser-item: failed to parse json", error);
		return fallback;
	}
};

const parseRecommendations = (value: string | null | undefined): AdvisorRecommendations[] => {
	if (!value) {
		return [];
	}
	try {
		return (JSON.parse(value) as AdvisorUtilities.AdvisorClassObject[]).map((entry) => entry.class);
	} catch (error) {
		console.error("production-chooser-item: failed to parse recommendations", error);
		return [];
	}
};

const normalizeCategory = (value?: string | null): ProductionPanelCategory => {
	switch (value) {
		case ProductionPanelCategory.UNITS:
			return ProductionPanelCategory.UNITS;
		case ProductionPanelCategory.PROJECTS:
			return ProductionPanelCategory.PROJECTS;
		case ProductionPanelCategory.WONDERS:
			return ProductionPanelCategory.WONDERS;
		default:
			return ProductionPanelCategory.BUILDINGS;
	}
};

interface ProductionChooserItemProps {
	attrs: AttrMap;
	host?: Element;
}

const ProductionChooserItemContent: Component<ProductionChooserItemProps> = (props) => {
	const attrs = () => props.attrs;

	createEffect(() => {
		props.host?.classList.add("text-base", "production-chooser-item");
		props.host?.removeAttribute("tabindex");
	});

	const category = createMemo(() => normalizeCategory(attrs()["data-category"]));
	const itemType = createMemo(() => attrs()["data-type"] ?? undefined);
	const isRepairAll = createMemo(() => attrs()["data-repair-all"] === "true");
	const nameKey = createMemo(() => attrs()["data-name"] ?? undefined);
	const descriptionKey = createMemo(() => attrs()["data-description"] ?? undefined);
	const isPurchase = createMemo(() => attrs()["data-is-purchase"] === "true");
	const isDisabled = createMemo(() => attrs()["data-disabled"] === "true");
	const disableFocus = createMemo(() => attrs()["data-disable-focus"] === "true");
	const isAgeless = createMemo(() => attrs()["data-is-ageless"] === "true");
	const infoDisplayType = createMemo(() => attrs()["data-info-display-type"] ?? undefined);
	const showAlternateYields = createMemo(() => infoDisplayType() === "base-yield");
	const showSecondaryDetails = createMemo(() => {
		const details = attrs()["data-secondary-details"];
		const displayType = infoDisplayType();
		// Show secondary details when infoDisplayType is not "base-yield" (i.e., for units with yield-preview or no type)
		return !!details && displayType !== "base-yield";
	});
	const warehouseCount = createMemo(() => attrs()["data-warehouse-count"] ?? undefined);
	const highestAdjacency = createMemo(() => attrs()["data-highest-adjacency"] ?? undefined);
	const canShowWarehouse = createMemo(() => attrs()["data-can-get-warehouse"] === "true" && !!warehouseCount());
	const canShowAdjacency = createMemo(() => attrs()["data-can-get-adjacency"] === "true" && !!highestAdjacency());
	const baseYields = createMemo<YieldValue[]>(() => parseJSON(attrs()["data-base-yields"], []));
	const showBaseYields = createMemo(() => baseYields().length > 0);
	const recommendations = createMemo(() => parseRecommendations(attrs()["data-recommendations"]));
	const showRecommendations = createMemo(() => recommendations().length > 0);
	const errorKey = createMemo(() => attrs()["data-error"] ?? undefined);
	const secondaryDetails = createMemo(() => attrs()["data-secondary-details"] ?? "");
	const isUnitType = createMemo(() => {
		const type = itemType();
		return !!type && !!GameInfo.Units.lookup(type);
	});
	const costValue = createMemo(() => attrs()["data-cost"] ?? "");
	const hideCost = createMemo(() => {
		const parsed = Number(costValue());
		return Number.isNaN(parsed) || parsed < 0;
	});
	const costIcon = createMemo(() => (isPurchase() ? "Yield_Gold" : "hud_turn-timer"));
	const costIconLabel = createMemo(() =>
		Locale.compose(isPurchase() ? "LOC_YIELD_GOLD" : "LOC_UI_CITY_INSPECTOR_TURNS"),
	);
	const audio = createMemo<ActivatableAudio | undefined>(() => {
		const group = attrs()["data-audio-group-ref"] ?? undefined;
		const onActivate = attrs()["data-audio-activate-ref"] ?? undefined;
		const onPress = attrs()["data-audio-press-ref"] ?? undefined;
		const onError = attrs()["data-audio-error-press-ref"] ?? undefined;
		const onFocus = attrs()["data-audio-focus-ref"] ?? undefined;
		if (!group && !onActivate && !onPress && !onError && !onFocus) {
			return undefined;
		}
		return { group, onActivate, onPress, onError, onFocus } satisfies ActivatableAudio;
	});

	return (
		<ProductionTooltip
			initialHPosition={TooltipHorizontalPosition.RIGHT}
			initialVPosition={TooltipVerticalPosition.CENTER}
			offset={30}
			category={category()}
			type={itemType()}
			name={nameKey()}
			description={descriptionKey()}
			recommendations={recommendations()}
			isPurchase={isPurchase()}
			cost={costValue()}
			warehouseCount={warehouseCount()}
			highestAdjacency={highestAdjacency()}
			canGetWarehouseBonuses={canShowWarehouse()}
			canGetAdjacencyBonuses={canShowAdjacency()}
		>
			<AudioContextProvider vars={{ isPurchase: isPurchase().toString() }}>
				<ChooserItem
					class="text-base production-chooser-item"
					contentClass="p-2 tracking-100 flex flex-row"
					name="ProductionChooserItem"
					selectOnActivate
					disabled={isDisabled()}
					audio={audio()}
					disableFocus={disableFocus()}
					data-category={category()}
					data-type={itemType()}
					data-repair-all={isRepairAll() ? "true" : undefined}
				>
					<div class="flex flex-row flex-auto items-stretch">
						<Icon
							class="size-16 bg-contain bg-center bg-no-repeat mr-2 flex-shrink-0 pointer-events-none"
							name={itemType()}
						/>
						<div class="relative flex flex-col flex-auto justify-between pt-2 pb-1.5">
							<span class="font-title text-accent-2 uppercase">
								<L10n.Compose text={nameKey() ?? ""} />
							</span>
							<Show when={errorKey()}>
								<span class="font-body text-negative-light z-1 pointer-events-none">
									<L10n.Compose text={errorKey()!} />
								</span>
							</Show>
							<Show when={showSecondaryDetails()}>
								<div
									class="flex text-sm"
									classList={{ "-ml-1.5": isUnitType() }}
									innerHTML={secondaryDetails()}
								/>
							</Show>
							<Show when={showAlternateYields()}>
								<div class="flex items-center text-sm production-chooser__font-icon-positioning">
									<Show when={showBaseYields()}>
										<div class="flex items-center">
											<For each={baseYields()}>
												{(yieldValue, index) => (
													<L10n.Stylize
														class={`flex items-center ${index() > 0 ? "ml-1" : ""}`}
														text="LOC_BUILDING_PLACEMENT_YIELD_ICON_ONLY"
														args={[yieldValue.value, yieldValue.yieldType]}
													/>
												)}
											</For>
										</div>
									</Show>
									<Show when={canShowWarehouse()}>
										<div class="flex items-center">
											<div class="mx-2">|</div>
											<div class="mx-1">{warehouseCount()}</div>
											<Icon
												class="size-8"
												name="YIELD_WAREHOUSE"
											/>
										</div>
									</Show>
									<Show when={canShowAdjacency()}>
										<div class="flex items-center">
											<div class="mx-2">|</div>
											<div class="mx-1">{highestAdjacency()}</div>
											<Icon
												class="size-8"
												name="YIELD_ADJACENCY"
											/>
										</div>
									</Show>
								</div>
							</Show>
						</div>
						<div class="flex flex-col justify-end">
							<div class="self-end">
								<Show when={isAgeless()}>
									<PillText text="LOC_UI_PRODUCTION_AGELESS" />
								</Show>
							</div>
							<div class="flex flex-auto self-end">
								<Show when={!hideCost()}>
									<div class="flex flex-row items-center self-end">
										<Show when={showRecommendations()}>
											<AdvisorRecommendationsList
												class="mr-2"
												recommendations={recommendations()}
												direction="horizontal"
												iconOnly={true}
												noWrap={true}
											/>
										</Show>
										<span>{costValue()}</span>
										<span
											class="size-8 bg-contain bg-center bg-no-repeat mr-1"
											style={{ "background-image": `url(${costIcon()})` }}
											aria-label={costIconLabel()}
										/>
									</div>
								</Show>
							</div>
						</div>
					</div>
				</ChooserItem>
			</AudioContextProvider>
		</ProductionTooltip>
	);
};

defineLegacyComponent(
	"production-chooser-item",
	{
		attrs: {
			"data-disabled": null,
			"data-disable-focus": "false",
			"data-category": null,
			"data-name": null,
			"data-type": null,
			"data-cost": null,
			"data-prereq": null,
			"data-description": null,
			"data-error": null,
			"data-is-purchase": null,
			"data-is-ageless": null,
			"data-secondary-details": null,
			"data-recommendations": null,
			"data-tags": null,
			"data-base-yields": null,
			"data-can-get-warehouse": null,
			"data-info-display-type": null,
			"data-warehouse-count": null,
			"data-can-get-adjacency": null,
			"data-highest-adjacency": null,
			"data-repair-all": null,
			"data-audio-group-ref": null,
			"data-audio-press-ref": null,
			"data-audio-activate-ref": null,
			"data-audio-error-press-ref": null,
			"data-audio-focus-ref": null,
		},
	},
	(attrs, element) => (
		<ProductionChooserItemContent
			attrs={attrs}
			host={element}
		/>
	),
);
